"""Interactive team and app selection for the publish command."""

import os
import sys
from dataclasses import dataclass
from typing import List, Optional

from rich.console import Console
from rich.prompt import IntPrompt, Prompt

from plotly_cloud._api_types import App, Team
from plotly_cloud._definitions import AppDeploymentConfig
from plotly_cloud.exceptions import ApplicationError

console = Console()


@dataclass
class PublishTarget:
    """Resolved publish identity: which team and which app."""

    team_id: Optional[str]
    app_id: Optional[str]
    app_name: Optional[str]
    app_url: Optional[str]
    is_new_app: bool


@dataclass
class AppDecision:
    """Outcome of app resolution: an existing app, create-new, or prompt-needed."""

    app: Optional[App]
    is_new_app: bool
    new_app_name: Optional[str]
    needs_prompt: bool


def is_interactive() -> bool:
    """Report whether the session can prompt the user."""
    if os.environ.get("CI", "").strip().lower() in ("true", "1"):
        return False
    return sys.stdin.isatty()


def resolve_team(
    teams: List[Team],
    team_flag: Optional[str],
    team_id_flag: Optional[str],
    interactive: bool,
) -> Optional[Team]:
    """Resolve the publish team.

    Returns the selected team, or None when an interactive prompt is needed.
    """
    if team_id_flag:
        for team in teams:
            if team.get("id") == team_id_flag:
                return team
        raise ApplicationError(
            f"Team with ID '{team_id_flag}' not found. "
            "Use 'plotly user teams' to list available teams."
        )

    if team_flag:
        for team in teams:
            if (
                team.get("name", "").lower() == team_flag.lower()
                or team.get("id", "").lower() == team_flag.lower()
            ):
                return team
        raise ApplicationError(
            f"Team '{team_flag}' not found. "
            "Use 'plotly user teams' to list available teams."
        )

    if not teams:
        raise ApplicationError("No teams found for your account. Unable to publish.")

    if len(teams) == 1:
        return teams[0]

    if interactive:
        return None

    raise ApplicationError(
        "Multiple teams available. Re-run with --team or --team-id to choose one."
    )


def resolve_app(
    apps: List[App],
    name_flag: Optional[str],
    app_id_flag: Optional[str],
    interactive: bool,
) -> AppDecision:
    """Resolve which app to publish to, or whether to create a new one."""
    if app_id_flag:
        for app in apps:
            if app.get("id") == app_id_flag:
                return AppDecision(
                    app=app, is_new_app=False, new_app_name=None, needs_prompt=False
                )
        raise ApplicationError(
            f"App with ID '{app_id_flag}' not found in this team. "
            "Use 'plotly app list' to see available apps."
        )

    if name_flag:
        return AppDecision(
            app=None, is_new_app=True, new_app_name=name_flag, needs_prompt=False
        )

    if interactive:
        return AppDecision(
            app=None, is_new_app=False, new_app_name=None, needs_prompt=True
        )

    raise ApplicationError(
        "No app specified. Re-run with --name to create a new app "
        "or --app-id to update an existing one."
    )


def prompt_team_selection(teams: List[Team]) -> Team:
    """Render a numbered team list and return the user's choice."""
    console.print("\n[bold]Select a team:[/bold]")
    for index, team in enumerate(teams, start=1):
        console.print(f"  {index}. {team.get('name') or team.get('id', 'unknown')}")
    choice = IntPrompt.ask(
        "Enter team number",
        choices=[str(i) for i in range(1, len(teams) + 1)],
        show_choices=False,
    )
    return teams[choice - 1]


def prompt_app_selection(apps: List[App], project_folder_name: str) -> AppDecision:
    """Render the app list and return the choice; a blank entry creates a new app."""
    if not apps:
        return _prompt_new_app_name(project_folder_name)

    console.print("\n[bold]Select an app to update, or press Enter to create a new one:[/bold]")
    for index, app in enumerate(apps, start=1):
        console.print(f"  {index}. {app.get('name') or app.get('id', 'unknown')}")

    valid_choices = {str(i) for i in range(1, len(apps) + 1)}
    while True:
        choice = Prompt.ask(
            "Enter app number (leave blank to create a new app)",
            default="",
            show_default=False,
        ).strip()
        if choice == "":
            return _prompt_new_app_name(project_folder_name)
        if choice in valid_choices:
            return AppDecision(
                app=apps[int(choice) - 1],
                is_new_app=False,
                new_app_name=None,
                needs_prompt=False,
            )
        console.print(f"[red]Enter a number between 1 and {len(apps)}, or leave blank.[/red]")


def _prompt_new_app_name(project_folder_name: str) -> AppDecision:
    """Ask for a new app name, defaulting to the project folder name."""
    name = Prompt.ask("Enter app name", default=project_folder_name).strip()
    if not name:
        raise ApplicationError("App name cannot be empty.")
    return AppDecision(app=None, is_new_app=True, new_app_name=name, needs_prompt=False)


def apply_target_to_config(
    config: AppDeploymentConfig, target: PublishTarget, app_url: Optional[str] = None
) -> None:
    """Write resolved identity into the config, skipping empty values."""
    if target.app_name:
        config["name"] = target.app_name
    if target.app_id:
        config["app_id"] = target.app_id
    resolved_url = app_url or target.app_url
    if resolved_url:
        config["app_url"] = resolved_url
